-- 3. The wrong-tech rows no unit uses now, each one checked on its own: one still in use (on a database with
-- other units) stays. Their slang links go with them (ON DELETE CASCADE), and so does a term left with none,
-- except the ones added by hand (USER), which slang loads keep too.
CREATE TEMPORARY TABLE v3_10_unused AS
